def b(lang: str, key: str, **kwargs) -> str:
    """Fail rather than falling back to another display language."""
    if lang not in TXT or key not in TXT[lang]:
        raise KeyError(f"Missing benchmark translation {lang}/{key}")
    return TXT[lang][key].format(**kwargs)
